INSERT INTO modules_meta (id, nombre, icon, descripcion, gestion, observacion, sla_dias, issues) VALUES ('pacienteep', 'Paciente Derivado EP', '🧑‍⚕️', 'Pacientes derivados a Evaluación Preventiva (EP) desde otros servicios.', '100.0% de los casos tiene gestión registrada.', 'No se detectaron RUT repetidos en este módulo.', 10, '[{"t": "Fecha de ingreso futura", "c": 4, "sev": "serious"}, {"t": "Atención posterior al ingreso", "c": 1, "sev": "critical"}]'::jsonb);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('critical', '533 solicitudes sin gestión registrada', 'De las 1.504 solicitudes analizadas, 533 no tienen ninguna evidencia de que alguien las haya trabajado (sin nombre de ejecutivo, sin nota de gestión, sin respuesta). El mayor volumen está en Otras Solicitudes (486 de 1.071, un 45%) y en CD Pendiente (44 de 201, un 22%). Son pacientes que pidieron algo — una boleta, una receta, una cita — y no hay registro de que se les haya respondido.', 'Priorizar el cierre de estos 533 casos partiendo por los más antiguos (ver “Fuera de SLA” en cada módulo). A futuro, hacer obligatorio dejar una nota de gestión antes de poder cerrar o archivar una solicitud.', 0);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('critical', 'Atención registrada después del ingreso (325+ casos)', 'La fecha de atención debería ser siempre anterior a la fecha en que se ingresó el caso (la atención ya ocurrió, y por eso el paciente pide el documento). Cuando aparece al revés, es una secuencia imposible: normalmente indica que se escribió mal una de las dos fechas.', 'Revisar caso a caso en la sección “Secuencia de fechas” de cada módulo — ahí se sugiere automáticamente la fecha corregida cuando el problema es un día/mes invertido, y se marca “revisar manualmente” cuando no se puede deducir.', 1);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('serious', '125 RUT que se repiten dentro de un mismo módulo', '125 números de RUT aparecen más de una vez dentro de la misma base (la mayoría en Otras Solicitudes e Informes Médicos). Puede ser un paciente que pidió lo mismo varias veces, o puede ser un caso duplicado que ya se atendió y se volvió a registrar por error.', 'Revisar los grupos de RUT repetido en la sección “RUT duplicados” de cada módulo antes de gestionar un caso nuevo — así se evita atender (o pagar) dos veces lo mismo.', 2);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('serious', '19 RUT mal escritos', '19 registros tienen un RUT que no es válido: vacío, con formato raro, o con un dígito verificador que no corresponde al número. En algunos casos el campo RUT tiene, por error, un correo o un nombre en vez de un RUT.', 'Corregir estos 19 casos en la base — el detalle exacto (fila, nombre y la corrección sugerida cuando existe) está disponible en la pestaña “Auditoría de RUT”.', 3);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('warning', 'Al menos 5 filas de prueba mezcladas con datos reales', 'Se detectaron registros como “Prueba”, RUT “1234”, o textos de prueba mezclados entre las solicitudes reales. Estas filas distorsionan cualquier conteo o estadística que se calcule sobre la base (SLA, gestión, calidad).', 'Eliminar o marcar claramente estas filas como “prueba” para que no se cuenten en las estadísticas de gestión.', 4);
INSERT INTO causas (sev, h, p, s, orden) VALUES ('warning', 'Calidad de la redacción: 700 solicitudes con detalle “Regular” y 24 “Deficiente”', 'Al revisar cómo quedó escrita la descripción de cada solicitud (mayúsculas sostenidas, sin tildes, doble espacio, o directamente muy corta como para entender qué pide el paciente), 700 quedaron en un nivel “Regular” y 24 en “Deficiente” — textos tan cortos que el siguiente ejecutivo no puede saber qué se necesita sin volver a contactar al paciente.', 'Pedir al equipo que, al registrar el detalle de una solicitud, escriba al menos una frase completa y clara — ayuda a que cualquier otro ejecutivo pueda retomar el caso sin tener que llamar de nuevo al paciente.', 5);
